// selectBooks.tsx
"use client";
import { useEffect, useState } from "react";
import { ReceiptText } from "lucide-react";

interface Book {
  id: number;
  name: string;
  price: number;
  store: string;
  available: boolean;
}

export default function SelectBooksPage() {
  const [books, setBooks] = useState<Book[]>([]);
  const [selectedBooks, setSelectedBooks] = useState<Book[]>([]);

  useEffect(() => {
    // Παίρνουμε τα βιβλία που επέλεξε ο χρήστης στη σελίδα confirmDeclaration
    const savedBooks = localStorage.getItem("selectedBooks");
    if (savedBooks) setBooks(JSON.parse(savedBooks));
  }, []);

  // Ομαδοποίηση βιβλίων ανά store
  const booksByStore = books.reduce((acc: Record<string, Book[]>, book) => {
    if (!acc[book.store]) acc[book.store] = [];
    acc[book.store].push(book);
    return acc;
  }, {});

  const toggleBook = (book: Book) => {
    if (selectedBooks.some(b => b.id === book.id)) {
      setSelectedBooks(selectedBooks.filter(b => b.id !== book.id));
    } else {
      setSelectedBooks([...selectedBooks, book]);
    }
  };

  const totalPrice = selectedBooks.reduce((sum, book) => sum + book.price, 0);

  return (
    <div className="container mx-auto py-6">
      <h1 className="text-3xl font-bold mb-6">Επίλεξε τα συγγράμματα</h1>

      <div className="grid gap-6">
        {Object.entries(booksByStore).map(([store, storeBooks]) => (
          <div key={store} className="border rounded-xl p-4 shadow-sm">
            <h2 className="text-xl font-semibold mb-4">{store}</h2>
            {storeBooks.map(book => (
              <label key={book.id} className="flex justify-between items-center mb-2">
                <div className="flex items-center gap-3">
                  <input
                    type="checkbox"
                    checked={selectedBooks.some(b => b.id === book.id)}
                    disabled={!book.available}
                    onChange={() => toggleBook(book)}
                    className="w-5 h-5 accent-primary-dark"
                  />
                  <span>{book.name}</span>
                </div>
                <span className={`px-3 py-1 rounded-full text-white ${book.available ? "bg-green-500" : "bg-red-400"}`}>
                  {book.available ? "Available" : "Unavailable"}
                </span>
              </label>
            ))}
          </div>
        ))}
      </div>

      <div className="mt-6 p-4 border rounded-xl shadow-md">
        <p className="font-bold">Total Price: {totalPrice} €</p>
      </div>
    </div>
  );
}
